const initialData = $('Initial').first().json || {};
const body = initialData.body || initialData || {};
const data = body.data || {};
const key = data.key || body.key || {};

const configData = $('Config').first().json || {};
const configList = Array.isArray(configData?.itens) ? configData.itens : [];
const configsMap = {};
configList.forEach(item => {
  if (item && item.key) configsMap[item.key] = item.value;
});

const messageId = key.id || '';
const fromMe = Boolean(key.fromMe);

// Ignora eventos que não sejam mensagens ou mensagens sem ID
if (!messageId) {
  return {
    json: {
      isValidMessage: false,
      reason: 'Evento sem key.id de mensagem.',
      configs: configsMap
    }
  };
}

// Identifica participante e se é grupo
const remoteJid = key.remoteJid || body.sender || '';
const isGroup = remoteJid.includes('@g.us') || remoteJid.includes('broadcast');

if (isGroup) {
  return {
    json: {
      isValidMessage: false,
      reason: 'Mensagem de grupo ou broadcast ignorada pelo monitor.',
      configs: configsMap
    }
  };
}

const rawClientPhone = (key.remoteJidAlt || remoteJid).split('@')[0].split(':')[0].replace(/\D/g, '');
const clientPhone = rawClientPhone.startsWith('55') ? rawClientPhone : ('55' + rawClientPhone);
const clientName = fromMe ? '' : (data.pushName || body.senderName || '').trim();

// Telefone da instância conectada da loja
const rawConnectedPhone = (body.sender || body.destination || data.owner || '').split('@')[0].split(':')[0].replace(/\D/g, '');
const connectedPhone = rawConnectedPhone.startsWith('55') ? rawConnectedPhone : ('55' + rawConnectedPhone);
const instanceName = body.instance || '';

// Tipo de mensagem e extração de conteúdo
const messageTypeRaw = String(data.messageType || '').toLowerCase();
let tipo = 'texto';
let conteudo = '';
let midiaUrl = '';
let isAudio = false;
let audioBase64 = '';

const msgObj = data.message || {};

if (messageTypeRaw.includes('audio') || msgObj.audioMessage) {
  tipo = 'audio';
  isAudio = true;
  audioBase64 = data.base64 || msgObj.audioMessage?.base64 || '';
  conteudo = '[Mensagem de Áudio]';
} else if (messageTypeRaw.includes('image') || msgObj.imageMessage) {
  tipo = 'imagem';
  conteudo = msgObj.imageMessage?.caption || '[Imagem]';
  midiaUrl = msgObj.imageMessage?.url || '';
} else if (messageTypeRaw.includes('video') || msgObj.videoMessage) {
  tipo = 'video';
  conteudo = msgObj.videoMessage?.caption || '[Vídeo]';
} else if (messageTypeRaw.includes('document') || msgObj.documentMessage) {
  tipo = 'documento';
  conteudo = msgObj.documentMessage?.title || msgObj.documentMessage?.fileName || '[Documento]';
} else if (msgObj.conversation) {
  tipo = 'texto';
  conteudo = msgObj.conversation;
} else if (msgObj.extendedTextMessage?.text) {
  tipo = 'texto';
  conteudo = msgObj.extendedTextMessage.text;
} else {
  tipo = 'texto';
  conteudo = msgObj.conversation || '[Mensagem]';
}

// Deteccao de Anuncios Meta / Instagram / Facebook (CTWA)
const contextInfo = msgObj.extendedTextMessage?.contextInfo || data.contextInfo || {};
const adReply = contextInfo.externalAdReply;
const isAd = contextInfo.conversionSource === 'FB_Ads' || contextInfo.entryPointConversionSource === 'ctwa_ad' || Boolean(adReply);

let dadosAds = {};
let origem = 'organico';

if (isAd && adReply) {
  const rawBody = adReply.body || '';
  const cleanBody = rawBody
    .split('\n')
    .map(line => line.trim())
    .filter(line => line && !line.startsWith('#'))
    .join(' ')
    .replace(/\s+/g, ' ')
    .trim();

  const resumoAd = cleanBody.length > 250 ? cleanBody.substring(0, 247) + '...' : cleanBody;
  const canal = (contextInfo.entryPointConversionApp || adReply.sourceApp || 'instagram').toLowerCase();

  origem = canal.includes('facebook') ? 'facebook_ads' : 'instagram_ads';

  dadosAds = {
    isAd: true,
    canal,
    conversaoOrigem: contextInfo.conversionSource || contextInfo.entryPointConversionSource || 'FB_Ads',
    adId: adReply.sourceId || '',
    adTitulo: adReply.title || '',
    adTema: resumoAd,
    sourceUrl: adReply.sourceUrl || '',
    mediaUrl: adReply.thumbnailUrl || adReply.mediaUrl || '',
    ctwaClid: adReply.ctwaClid || ''
  };
}

// Timestamp real do WhatsApp (Evolution API entrega em data.messageTimestamp ou body.date_time)
let messageTimestampIso = null;
let messageTimestampSeconds = null;
const rawTs = data.messageTimestamp || body.data?.messageTimestamp || body.date_time;
if (rawTs) {
  const numTs = Number(rawTs);
  if (!isNaN(numTs) && numTs > 0) {
    messageTimestampSeconds = numTs > 9999999999 ? Math.floor(numTs / 1000) : numTs;
    messageTimestampIso = new Date(messageTimestampSeconds * 1000).toISOString();
  } else {
    const d = new Date(rawTs);
    if (!isNaN(d.getTime())) {
      messageTimestampSeconds = Math.floor(d.getTime() / 1000);
      messageTimestampIso = d.toISOString();
    }
  }
}
if (!messageTimestampIso) {
  messageTimestampIso = new Date().toISOString();
  messageTimestampSeconds = Math.floor(Date.now() / 1000);
}

const headers = initialData.headers || {};
const query = initialData.query || {};
const incomingAuthKey = String(
  headers['apikey'] ||
  headers['x-evolution-apikey'] ||
  headers['x-webhook-secret'] ||
  (headers['authorization'] || '').replace(/^Bearer\s+/i, '') ||
  query['apikey'] ||
  query['token'] ||
  query['secret'] ||
  body.apikey ||
  ''
).trim();

return {
  json: {
    isValidMessage: true,
    configs: configsMap,
    incomingAuthKey,
    messageId,
    fromMe,
    direcao: fromMe ? 'outbound' : 'inbound',
    instanceName,
    connectedPhone,
    clientPhone,
    clientName,
    tipo,
    conteudo,
    midiaUrl,
    isAudio,
    audioBase64,
    hasAudioBase64: Boolean(audioBase64),
    isAd,
    dadosAds,
    origem,
    timestamp_mensagem: messageTimestampIso,
    timestamp_seconds: messageTimestampSeconds,
    rawPayload: body
  }
};

const meta = $('Extrair Metadados').item.json;
const loja = $('Identificar Loja').item.json;

// Se veio transcrição do Gemini, usa ela
let conteudoFinal = meta.conteudo;
if ($input.item.json?.content?.parts?.[0]?.text) {
  conteudoFinal = $input.item.json.content.parts[0].text.trim();
}

let dadosAds = meta.dadosAds || {};
let isAd = Boolean(meta.isAd && (dadosAds.adId || dadosAds.adTitulo || dadosAds.adTema));
let origem = meta.origem || 'organico';
let adId = dadosAds.adId || '';
let adTitulo = dadosAds.adTitulo || '';
let adTema = dadosAds.adTema || '';
let adCanal = dadosAds.canal || 'instagram';
let sourceUrl = dadosAds.sourceUrl || '';
let mediaUrl = dadosAds.mediaUrl || meta.midiaUrl || '';
let ctwaClid = dadosAds.ctwaClid || '';

// Funcao de normalizacao rigorosa: sem acentos, sem pontuacao, maiusculas
const normalizeText = (txt) => {
  return String(txt || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-zA-Z0-9\s]/g, ' ')
    .toUpperCase()
    .replace(/\s+/g, ' ')
    .trim();
};

// Prioridade 2: Se NAO for Meta Ads e for inbound, verifica palavras-chave Google Ads da loja
if (!isAd && meta.direcao === 'inbound') {
  const lojaConfig = loja.config_json || {};
  const rawKeywords = String(lojaConfig.google_ads_keywords || '').trim();

  if (rawKeywords) {
    const normalizedConteudo = normalizeText(conteudoFinal);
    const keywordsList = rawKeywords
      .split(',')
      .map(k => k.trim())
      .filter(Boolean);

    for (const kw of keywordsList) {
      const cleanKw = normalizeText(kw);
      if (cleanKw.length >= 2 && normalizedConteudo.includes(cleanKw)) {
        isAd = true;
        origem = 'google_ads';
        adCanal = 'google';
        adId = 'google_' + cleanKw.replace(/\s+/g, '_');
        adTitulo = kw.trim();
        adTema = 'Anúncio Google via palavra-chave/cupom: ' + kw.trim();
        sourceUrl = '';
        mediaUrl = '';
        dadosAds = {
          isAd: true,
          canal: 'google',
          conversaoOrigem: 'google_keywords',
          adId: adId,
          adTitulo: adTitulo,
          adTema: adTema,
          termoMatch: kw.trim(),
          sourceUrl: '',
          mediaUrl: ''
        };
        break;
      }
    }
  }
}

return {
  json: {
    loja_id: loja.id,
    loja_nome: loja.nome,
    cliente_nome: meta.direcao === 'outbound' ? '' : (meta.clientName || 'Contato WhatsApp'),
    cliente_whatsapp: meta.clientPhone,
    origem: origem,
    is_ad: isAd,
    ad_id: adId,
    ad_titulo: adTitulo,
    ad_tema: adTema,
    ad_canal: adCanal,
    source_url: sourceUrl,
    media_url: mediaUrl,
    ctwa_clid: ctwaClid,
    dadosAds: dadosAds,
    message_id: meta.messageId,
    direcao: meta.direcao,
    tipo: meta.tipo,
    conteudo: conteudoFinal,
    midia_url: meta.midiaUrl,
    timestamp_mensagem: meta.timestamp_mensagem,
    timestamp_seconds: meta.timestamp_seconds,
    configs: meta.configs || {}
  }
};

