const resp = $input.item.json;
const configs = $('Extrair Metadados').item.json.configs || {};
const crypto = require('crypto');

const appId = (configs.pusher_app_id || '').trim();
const key = (configs.pusher_key || '').trim();
const secret = (configs.pusher_secret || '').trim();
const cluster = (configs.pusher_cluster || 'us2').trim();

if (!appId || !key || !secret) {
  return {
    json: {
      hasPusher: false,
      resp
    }
  };
}

const channels = ['adswhats-global'];
if (resp.loja_id) {
  channels.push('loja-' + resp.loja_id);
}

const eventData = {
  loja_id: resp.loja_id,
  pessoa_id: resp.pessoa_id,
  mensagem_id: resp.mensagem_id,
  message_id: resp.message_id,
  is_ad: resp.is_ad,
  origem: resp.origem,
  tipo: resp.tipo
};

const payload = {
  name: 'nova-mensagem',
  channels: channels,
  data: JSON.stringify(eventData)
};

const bodyString = JSON.stringify(payload);
const bodyMd5 = crypto.createHash('md5').update(bodyString).digest('hex');
const authTimestamp = Math.floor(Date.now() / 1000);
const method = 'POST';
const path = '/apps/' + appId + '/events';

const stringToSign = method + '\n' + path + '\nauth_key=' + key + '&auth_timestamp=' + authTimestamp + '&auth_version=1.0&body_md5=' + bodyMd5;
const authSignature = crypto.createHmac('sha256', secret).update(stringToSign).digest('hex');

const publishUrl = 'https://api-' + cluster + '.pusher.com' + path + '?auth_key=' + key + '&auth_timestamp=' + authTimestamp + '&auth_version=1.0&body_md5=' + bodyMd5 + '&auth_signature=' + authSignature;

return {
  json: {
    hasPusher: true,
    publishUrl,
    payload,
    resp
  }
};
